namespace sv_3bb399998fae4b9684112b6e656dd386.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public record StatusUpdate(DateTimeOffset Timestamp, string Description);

using sv_3bb399998fae4b9684112b6e656dd386.Client.Services;

namespace sv_3bb399998fae4b9684112b6e656dd386.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 6, 14, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 8, 9, 0, 0, TimeSpan.Zero), "Package picked up from sender"),
                new(new DateTimeOffset(2026, 6, 9, 14, 30, 0, TimeSpan.Zero), "Arrived at sorting facility - Chicago, IL"),
                new(new DateTimeOffset(2026, 6, 10, 6, 15, 0, TimeSpan.Zero), "In transit to destination"),
            }),
        ["TRK-002"] = new ShipmentDetails(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            new DateTimeOffset(2026, 6, 9, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 6, 10, 0, 0, TimeSpan.Zero), "Package picked up from sender"),
                new(new DateTimeOffset(2026, 6, 7, 8, 45, 0, TimeSpan.Zero), "Arrived at regional hub - Dallas, TX"),
                new(new DateTimeOffset(2026, 6, 8, 11, 20, 0, TimeSpan.Zero), "Out for delivery"),
                new(new DateTimeOffset(2026, 6, 8, 14, 5, 0, TimeSpan.Zero), "Delivered - Left at front door"),
            }),
        ["TRK-003"] = new ShipmentDetails(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            new DateTimeOffset(2026, 6, 18, 20, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 10, 0, 30, 0, TimeSpan.Zero), "Label created, awaiting pickup"),
            }),
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_3bb399998fae4b9684112b6e656dd386.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<Shipment> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <h2>Shipment @_shipment.TrackingNumber</h2>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h3>Tracking History</h3>
    <ul>
        @foreach (var update in _shipment.Updates)
        {
            <li><strong>@update.Timestamp.ToString("g")</strong> &mdash; @update.Description</li>
        }
    </ul>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed; do nothing
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

